import React, { useState, useEffect } from "react";
import { ip_address } from "../user/ipaddress";
import { Link } from "react-router-dom";
import { Menu, Dropdown, Button, Drawer, Modal } from "antd";
import { UserOutlined, MenuOutlined } from "@ant-design/icons";

import Swal from "sweetalert2";
import Carregister from "../user/carregister.js";

const Navbar = () => {
  const [visible, setVisible] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 600);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const showModal = () => {
    setIsModalOpen(true);
  };

  const handleClick = async () => {
    try {

      const response = await fetch(`${ip_address}/user/signout`);
      if (response.ok) {
        const data = await response.json();
        const status = data.status;
        switch (status) {
          case 200:
            console.log("성공");
            window.location.href = "/"; // 200 메시지가 뜨면 '/'로 이동
            break;
          case 400:
            console.log("정보 없음");
            Swal.fire("오류", data.error.message, "error"); // 서버에서 반환하는 메시지를 사용
            break;
          case 500:
            console.log("서버 오류");
            Swal.fire("오류", data.error.message, "error"); // 서버에서 반환하는 메시지를 사용
            break;
          default:
            console.log("알 수 없는 상태 코드:", status);
            Swal.fire("오류", "알 수 없는 오류가 발생했습니다.", "error");
        }
      }
    } catch (error) {
      console.log("Error fetching data:", error.message);
      Swal.fire("오류", "데이터를 가져오는 중 오류가 발생했습니다.", "error");
    }
  };

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth <= 600) {
        setIsMobile(true);
      } else {
        setIsMobile(false);
      }
    };

    window.addEventListener("resize", handleResize);

    return () => {
      // Cleanup the event listener on component unmount
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  const items = [
    {
      key:'0',
      label:'profile',
      onClick: ()=>{}
  },
  {
    key:'1',
    label:'Setting',
    onClick:()=>{}
  },
  {
    key:'2',
    label:'Logout',
    onClick:handleClick
  },
  ]
const itemsProps ={
  items,
};
const menuItems = [
  {
    label: <Link to="/" style={{ textDecoration: "none" }}>Home</Link>,
    key: "home"
  },
  {
    label: "차량등록",
    key: "carManagement",
    onClick: showModal
  },
  {
    label: "커뮤니티",
    key: "community",
    children: [
      {
        label: <Link to="/noticeboard" style={{ textDecoration: "none" }}>공지사항</Link>,
        key: "announcement"
      },
      {
        label: <Link to="/noticeboardwrite" style={{ textDecoration: "none" }}>민원</Link>,
        key: "complaint"
      }
    ]
  },
  {
    label: "편의기능",
    key: "convenience",
    children: [
      {
        label: <Link to="/news" style={{ textDecoration: "none" }}>최신뉴스</Link>,
        key: "news"
      },
      {
        label: "재난 문자",
        key: "disasterMsg"
      },
      {
        label: <Link to="/trash" style={{ textDecoration: "none" }}>주변 쓰레기통 정보</Link>,
        key: "publicTransport"
      },
      {
        label: "주변 병의원/약국정보",
        key: "hospitalPharmacy"
      }
    ]
  }
]

  return (
    <>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          borderBottom: "3px solid #f0f0f0",
        }}
      >
        <Link
          to="/"
          style={{
            padding: "0 16px",
            fontSize: "20px",
            fontWeight: "bold",
            color: "#1890ff",
            textDecoration: "none",
          }}
        >
          Eureka
        </Link>
        {!isMobile && <Menu items={menuItems} mode={"horizontal"} />}
        <div>
          {isMobile && (
            <Button
              icon={<MenuOutlined />}
              onClick={() => setVisible(true)}
              style={{ border: "none" }}
            />
          )}
          <Dropdown
            menu={itemsProps}
            trigger={isMobile ? ["click"] : ["hover"]}
          >
            <Button type="text" icon={<UserOutlined />} />
          </Dropdown>
        </div>
        <Drawer
          title="Menu"
          placement="right"
          closable={false}
          onClose={() => setVisible(false)}
          open={visible}
          bodyStyle={{ padding: 0 }}
          width="80%"
        >
          <Menu items={menuItems} mode={"inline"}  />
        </Drawer>
        <Modal
          open={isModalOpen}
          onCancel={() => setIsModalOpen(false)}
          footer={null}
        >
          <Carregister />
        </Modal>
      </div>
      <style jsx="true">{`
        /* 여기에 CSS 스타일을 추가하세요. */
      `}</style>
    </>
  );
};

export default Navbar;
