import React, { useEffect, useRef, useState } from "react";
import NavBar from "./navbar";
import axios from "axios";

function Trash() {
  const mapRef = useRef(null);
  const [markerInfo, setMarkerInfo] = useState([]);
  const [selectedMarkers, setSelectedMarkers] = useState([]);

  useEffect(() => {
    const script = document.createElement("script");
    script.type = "text/javascript";
    script.src =
      "https://openapi.map.naver.com/openapi/v3/maps.js?ncpClientId=l936h8b1w5";
    script.onload = () => {
      const getLocation = () => {
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(showPosition);
        } else {
          alert("Geolocation을 지원하지 않는 브라우저입니다.");
        }
      };

      const showPosition = (position) => {
        const latitude = position.coords.latitude;
        const longitude = position.coords.longitude;

        const mapOptions = {
          center: new window.naver.maps.LatLng(latitude, longitude),
          zoom: 10,
        };

        const map = new window.naver.maps.Map(mapRef.current, mapOptions);
        window.naverMap = map;

        axios
          .post(
            "https://apis.uiharu.dev/findbin/api.php",
            JSON.stringify({ latitude, longitude, distance: 1000 })
          )
          .then((response) => {
            const data = response.data;
            if (Array.isArray(data)) {
              data.forEach((item) => {
                if (item.latitude && item.longitude) {
                  const marker = new window.naver.maps.Marker({
                    position: new window.naver.maps.LatLng(
                      item.latitude,
                      item.longitude
                    ),
                    map: map,
                  });

                  window.naver.maps.Event.addListener(marker, "click", function (e) {
                    setSelectedMarkers((prevMarkers) => [...prevMarkers, item]);
                  });
                }
              });
            }
          })
          .catch((error) => {
            console.error("API 요청 중에 문제가 발생했습니다:", error);
          });
      };

      getLocation();
    };

    document.head.appendChild(script);

    return () => {
      document.head.removeChild(script);
    };
  }, []);

  return (
    <>
      <NavBar />
      <div
        style={{
          padding: "20px",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div ref={mapRef} style={{ width: "70%", height: "70vh", margin: "0 auto" }}></div>
      </div>
      <table>
        <thead>
          <tr>
            <th>Road Address</th>
          </tr>
        </thead>
        <tbody>
          {selectedMarkers.map((marker, index) => (
            <tr key={index}>
              <td>{marker.road_address}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

export default Trash;
